// Connect-ES API client — calls real backend via Connect-RPC.
// TS types generated by buf/protoc-gen-es (web/src/gen/.../srv_pb.ts).
//
// NOTE: the service descriptors are imported from the protoc-gen-es v2 files
// (*_pb.ts), which export GenService descriptors (structurally a DescService
// backed by serviceDesc(...)). The sibling *_connect.ts files were emitted by
// the older protoc-gen-connect-es v1 and reference message classes that no
// longer exist as values in the v2 proto code, so they neither type-check
// against the v2 runtime nor bundle. Importing from *_pb.ts gives full type
// inference for createClient with no casts.
import { createConnectTransport } from '@connectrpc/connect-web'
import { createClient, type Interceptor } from '@connectrpc/connect'
import { CatalogService, CatalogAdminService } from './gen/platform/v1/catalog/srv_pb.js'
import { RegistryAdminService } from './gen/platform/v1/registry/srv_pb.js'
import { LifecycleService } from './gen/platform/v1/lifecycle/srv_pb.js'
import { ApprovalDecision, RequestStatus as ProtoRequestStatus } from './gen/platform/v1/common/enum_pb.js'

// Transport: Connect-ES over HTTP to the Go backend.
// In dev, Vite proxies to localhost:8080. In production (go:embed), same origin.
const baseUrl = import.meta.env.DEV ? 'http://localhost:8080' : ''

// Attach the bearer token from localStorage to every outgoing request.
const authInterceptor: Interceptor = (next) => async (req) => {
  const token = localStorage.getItem('aether_token')
  if (token) {
    req.header.set('Authorization', `Bearer ${token}`)
  }
  return next(req)
}

export const transport = createConnectTransport({
  baseUrl,
  interceptors: [authInterceptor],
})

// Typed Connect clients. Fully typed via the v2 GenService descriptors.
export const catalogClient = createClient(CatalogService, transport)
export const catalogAdminClient = createClient(CatalogAdminService, transport)
export const registryClient = createClient(RegistryAdminService, transport)
export const lifecycleClient = createClient(LifecycleService, transport)

// === High-level API functions (used by pages) ===

export async function fetchCatalogItems() {
  const resp = await catalogClient.listItems({})
  return (resp.items || []).map(mapCatalogItem)
}

export async function fetchRequests() {
  const resp = await lifecycleClient.listRequests({})
  return (resp.requests || []).map(mapRequest)
}

export async function fetchPendingApprovals() {
  const resp = await lifecycleClient.listPendingApprovals({})
  // The backend returns approval runs (one per pending request). Map each run
  // into the display IaCRequest shape so the approvals table can render it.
  return (resp.runs || []).map((run: any) =>
    mapRequest({
      id: run.requestId,
      status: run.status,
      catalogItemId: '',
      envId: '',
      teamId: run.teamId || '',
      createdAt: run.startedAt || run.decidedAt || '',
    }),
  )
}

export async function fetchModules() {
  const resp = await registryClient.listModules({})
  return (resp.modules || []).map(mapModule)
}

// getCatalogItemDetail fetches a single catalog item including its
// form_schema_json (used to drive the RJSF dynamic request form).
export async function getCatalogItemDetail(id: string): Promise<CatalogItemDetail> {
  const resp = await catalogClient.getCatalogItem({ catalogItemId: id })
  const item = resp.item
  return {
    id: item?.id || id,
    name: item?.name || '',
    description: item?.description || '',
    category: item?.category || '',
    layer: item?.layerLogicalId || '',
    owner: item?.ownerTeamId || '',
    status: item?.status?.toString() || '',
    formSchemaJson: item?.formSchemaJson || '',
  }
}

export interface CatalogItemDetail extends CatalogItem {
  description: string
  formSchemaJson: string
}

// createRequest submits a lifecycle request. formData is the RJSF output
// (possibly nested / non-string values); it is flattened to map<string,string>
// to match the proto CreateRequest.form_values contract — each leaf value is
// JSON.stringified so the backend can recover typed values via json.Unmarshal.
export async function createRequest(input: {
  catalogItemId: string
  envId: string
  teamId: string
  formData: Record<string, unknown>
}): Promise<{ requestId: string; correlationId: string }> {
  const formValues: Record<string, string> = {}
  for (const [k, v] of Object.entries(input.formData || {})) {
    formValues[k] = typeof v === 'string' ? v : JSON.stringify(v)
  }
  const resp = await lifecycleClient.createRequest({
    catalogItemId: input.catalogItemId,
    envId: input.envId,
    teamId: input.teamId,
    formValues,
  })
  return {
    requestId: resp.request?.id || '',
    correlationId: resp.correlationId || '',
  }
}

export interface RegisterModuleInput {
  gitSource: string
  modulePath: string
  version: string
  provider: string
  name: string
  description?: string
  ownerTeamId: string
}

export interface RegisterModuleResult {
  moduleId: string
  moduleVersionId: string
  version: string
  status: string
}

// registerModule calls RegistryAdminService.RegisterModule and returns the new
// module + module_version IDs so the caller can immediately publish.
export async function registerModule(input: RegisterModuleInput): Promise<RegisterModuleResult> {
  const resp = await registryClient.registerModule({
    gitSource: input.gitSource,
    modulePath: input.modulePath,
    version: input.version,
    provider: input.provider,
    name: input.name,
    description: input.description ?? '',
    ownerTeamId: input.ownerTeamId,
  })
  const mod = resp.module
  const version = (mod?.versions && mod.versions[0]?.version) || input.version
  return {
    moduleId: mod?.id || '',
    moduleVersionId: resp.moduleVersionId || '',
    version,
    status: mod?.status?.toString() || '',
  }
}

export interface PublishCatalogInput {
  moduleVersionId: string
  displayName: string
  description?: string
  category: string
  layerLogicalId?: string
  ownerTeamId: string
  visibility?: string[]
}

// publishCatalogItem calls CatalogAdminService.PublishCatalogItem. The backend
// generates form_schema_json + defaults from the module version contract.
export async function publishCatalogItem(input: PublishCatalogInput): Promise<CatalogItem> {
  const resp = await catalogAdminClient.publishCatalogItem({
    moduleVersion: input.moduleVersionId,
    name: input.displayName,
    description: input.description ?? '',
    category: input.category,
    layerLogicalId: input.layerLogicalId ?? '',
    ownerTeamId: input.ownerTeamId,
    visibleToTeams: input.visibility ?? [],
  })
  return mapCatalogItem(resp.item)
}

export async function decideApproval(requestId: string, decision: 'approved' | 'rejected') {
  // The lifecycle RPC takes a run id + a numeric ApprovalDecision enum.
  await lifecycleClient.decideApproval({
    runId: requestId,
    decision: decision === 'approved' ? ApprovalDecision.APPROVED : ApprovalDecision.REJECTED,
  })
}

export async function fetchRequestDetail(id: string): Promise<RequestDetail> {
  const resp = await lifecycleClient.getRequest({ requestId: id })
  const r = mapRequest(resp.request || {})
  const rawStatus = (resp.request as any)?.status
  const statusKey = statusToKey(rawStatus ?? r.status)
  const statusName = statusToName(rawStatus ?? r.status)

  // Derive pipeline steps from the real lifecycle status. Each step maps to a
  // stage; finished = already past, process = current, wait = not yet reached,
  // error = the request died here.
  const statusNum = Number(rawStatus)
  const isError =
    statusNum === ProtoRequestStatus.FAILED_TERMINAL ||
    statusNum === ProtoRequestStatus.REJECTED ||
    statusNum === ProtoRequestStatus.CANCELLED ||
    statusKey === 'failed'

  // StepStatus mirrors RequestDetail.steps[].status so the helper return values
  // and local mutables stay assignable without literal-widening to string.
  type StepStatus = 'finish' | 'process' | 'wait' | 'error'

  const stepFor = (name: ProtoRequestStatus): StepStatus => {
    if (statusNum === name) return isError ? 'error' : 'process'
    return 'wait'
  }

  const submittedStep: StepStatus =
    statusNum === ProtoRequestStatus.SUBMITTED
      ? isError
        ? 'error'
        : 'process'
      : 'finish'

  let planStep: StepStatus = 'wait'
  if (
    statusNum === ProtoRequestStatus.PENDING_ADMISSION ||
    statusNum === ProtoRequestStatus.PLANNING
  ) {
    planStep = isError ? 'error' : 'process'
  } else if (
    statusNum === ProtoRequestStatus.PLAN_READY ||
    statusNum === ProtoRequestStatus.PENDING_APPROVAL ||
    statusNum === ProtoRequestStatus.APPLYING ||
    statusNum === ProtoRequestStatus.RECONCILING ||
    statusNum === ProtoRequestStatus.SUCCEEDED ||
    statusNum === ProtoRequestStatus.RECONCILE_PENDING ||
    statusNum === ProtoRequestStatus.WAITING_MANUAL
  ) {
    planStep = 'finish'
  }

  let applyStep: StepStatus = 'wait'
  if (
    statusNum === ProtoRequestStatus.APPLYING ||
    statusNum === ProtoRequestStatus.RECONCILING ||
    statusNum === ProtoRequestStatus.RECONCILE_PENDING
  ) {
    applyStep = isError ? 'error' : 'process'
  } else if (statusNum === ProtoRequestStatus.SUCCEEDED) {
    applyStep = 'finish'
  }

  const doneStep: StepStatus =
    statusNum === ProtoRequestStatus.SUCCEEDED ? 'finish' : 'wait'

  const steps: { title: string; description: string; status: StepStatus }[] = [
    { title: '提交', description: '工单已提交', status: submittedStep },
    { title: '代码生成', description: 'codegen 生成 HCL', status: stepFor(ProtoRequestStatus.GENERATING) },
    { title: 'Plan', description: 'Terraform Plan', status: planStep },
    {
      title: '审批',
      description: '人工审批门禁',
      status: stepFor(ProtoRequestStatus.PENDING_APPROVAL),
    },
    { title: 'Apply', description: 'Terraform Apply', status: applyStep },
    { title: '完成', description: '资源就绪', status: doneStep },
  ]

  // Build the timeline from real events (newest first → reverse so oldest is
  // first for chronological display). Fall back to a single submit row.
  const events = await fetchRequestEvents(id)
  const timeline = events.length
    ? [...events]
        .sort((a, b) => (a.occurredAt < b.occurredAt ? -1 : 1))
        .map((ev) => ({
          color: ev.toStatus === 'SUCCEEDED' ? 'green' : 'blue',
          content: ev.message || ev.stage || ev.eventType || ev.toStatus || '状态变更',
          time: ev.occurredAt,
        }))
    : [{ color: 'green', content: '提交工单', time: r.createdAt }]

  // Try to fetch the plan diff summary. getArtifact requires a plan_artifact_id
  // from the request; when missing/empty the backend rejects it, so guard.
  let planDiff = ''
  if (r.planArtifactId) {
    try {
      const art = await lifecycleClient.getArtifact({ artifactId: r.planArtifactId })
      const summary = art.artifact?.summary
      if (summary) {
        planDiff =
          `# Plan 摘要 (plan_hash: ${art.artifact?.planHash || '-'})\n\n` +
          `Terraform will perform the following actions:\n` +
          `  + ${summary.resourcesToAdd} to add\n` +
          `  ~ ${summary.resourcesToChange} to change\n` +
          `  - ${summary.resourcesToDestroy} to destroy\n`
      }
    } catch {
      // artifact not available yet (e.g. plan not finished); leave empty
    }
  }

  return {
    id: r.id || id,
    statusKey,
    statusName,
    steps,
    timeline,
    planDiff,
    info: [
      { label: '资源', value: r.catalogItem },
      { label: '环境', value: r.env },
      { label: '团队', value: r.team },
      { label: '状态', value: statusName },
    ],
  }
}

// === Type mappings (proto → frontend display types) ===

export type CatalogLayer = 'global' | 'middleware' | 'application'
export type CatalogCategory = 'database' | 'compute' | 'network' | 'storage' | 'middleware'
export type CatalogStatus = 'published' | 'draft' | 'deprecated'

// Env values cover both what the UI surfaces (dev/staging/prod) and the
// optional DR environment; backend values are mapped to these in mapRequest.
export type Env = 'dev' | 'staging' | 'prod' | 'dr'

// Status unions include both backend lifecycle values (from proto enums) and
// the human-facing values the pages render. Members intentionally form a
// superset so that Record<RequestStatus, string> tables in the pages are
// exhaustive regardless of which lifecycle value the backend returns.
export type RequestStatus =
  | 'succeeded'
  | 'pending_approval'
  | 'applying'
  | 'failed_terminal'
  | 'plan_ready'
  | 'generating'
  | 'failed_retryable'
  | 'rejected'
  | 'cancelled'
  | 'waiting_manual'
  | 'submitted'
  // UI-facing lifecycle values rendered by the pages:
  | 'draft'
  | 'code_generated'
  | 'completed'
  | 'failed'

// Module registry status values from the registry proto + UI-facing values.
export type ModuleStatus =
  | 'validated'
  | 'validation_failed'
  | 'deprecated'
  | 'ready'
  | 'extracting'
  | 'failed'
  | 'pending_validation'

export interface CatalogItem {
  id: string
  name: string
  category: string
  layer: string
  owner: string
  status: string
}

export interface IaCRequest {
  id: string
  catalogItem: string
  env: string
  status: string
  team: string
  createdAt: string
  // planArtifactId: set by mapRequest from the proto field of the same name.
  // Used by fetchRequestDetail to look up the plan summary; not rendered in
  // list rows directly.
  planArtifactId?: string
}

export interface Module {
  id: string
  name: string
  gitSource: string
  modulePath: string
  version: string
  provider: string
  varCount: number
  outputCount: number
  status: string
  contractJson?: string
  // moduleVersionId: snowflake ID of the current version, when surfaced by the
  // backend (ModuleVersion proto has no id field, so this is populated from the
  // register response and left empty for list rows — publishing from a list row
  // uses the dedicated publish modal where the operator supplies it).
  moduleVersionId?: string
}

export interface ApprovalItem extends IaCRequest {}

export interface RequestDetail {
  id: string
  // The raw proto status name (e.g. 'PLAN_READY') and the UI-facing key the
  // pages render as a Tag. statusKey is derived from statusToKey().
  statusKey: RequestStatus
  statusName: string
  steps: { title: string; description: string; status: 'finish' | 'process' | 'wait' | 'error' }[]
  timeline: { color: string; content: string; time?: string }[]
  planDiff: string
  info: { label: string; value: string }[]
}

// RequestEvent is the frontend-facing view of a LifecycleEvent row, used to
// render the status timeline on the request detail page.
export interface RequestEvent {
  id: string
  requestId: string
  eventType: string
  stage: string
  message: string
  fromStatus: string
  toStatus: string
  occurredAt: string
  actorId: string
}

// fetchRequestEvents calls LifecycleService.ListRequestEvents and maps each
// LifecycleEvent into the frontend RequestEvent shape. Errors are swallowed
// (returns []) because events are best-effort enrichment for the timeline.
export async function fetchRequestEvents(requestId: string): Promise<RequestEvent[]> {
  try {
    const resp = await lifecycleClient.listRequestEvents({ requestId, pageSize: 100 })
    return (resp.events || []).map((ev: any) => ({
      id: ev.id || '',
      requestId: ev.requestId || requestId,
      eventType: ev.eventType || '',
      stage: ev.stage || '',
      message: ev.message || '',
      fromStatus: ev.fromStatus || '',
      toStatus: ev.toStatus || '',
      occurredAt: ev.occurredAt || '',
      actorId: ev.actor?.id || '',
    }))
  } catch {
    return []
  }
}

// statusToKey converts a backend LifecycleRequest status (numeric enum or
// stringified number from mapRequest) into the human-facing RequestStatus key
// the pages render as Tags. Returns the raw value when unknown so the UI can
// surface unexpected backend values instead of hiding them.
export function statusToKey(status: string | number): RequestStatus {
  const num = typeof status === 'number' ? status : Number(status)
  if (!Number.isNaN(num)) {
    switch (num as ProtoRequestStatus) {
      case ProtoRequestStatus.SUBMITTED:
        return 'submitted'
      case ProtoRequestStatus.GENERATING:
        return 'generating'
      case ProtoRequestStatus.PLAN_READY:
        return 'plan_ready'
      case ProtoRequestStatus.PENDING_APPROVAL:
        return 'pending_approval'
      case ProtoRequestStatus.APPLYING:
        return 'applying'
      case ProtoRequestStatus.SUCCEEDED:
        return 'completed'
      case ProtoRequestStatus.REJECTED:
        return 'rejected'
      case ProtoRequestStatus.CANCELLED:
        return 'cancelled'
      case ProtoRequestStatus.FAILED_RETRYABLE:
        return 'failed_retryable'
      case ProtoRequestStatus.FAILED_TERMINAL:
        return 'failed'
      case ProtoRequestStatus.WAITING_MANUAL:
        return 'waiting_manual'
      default:
        // other enum values (planning/pending_admission/reconciling/etc.) fall
        // through to a 'draft'-style default that the UI treats as in-progress.
        return 'draft'
    }
  }
  return (status as RequestStatus) || 'draft'
}

// statusToName converts a backend status (numeric enum) into the SCREAMING_SNAKE
// name used to derive steps + timeline labels on the detail page. Falls back to
// the numeric value when the enum is unrecognized.
export function statusToName(status: string | number): string {
  const num = typeof status === 'number' ? status : Number(status)
  if (!Number.isNaN(num)) {
    const name = (ProtoRequestStatus as any)[num]
    if (typeof name === 'string') return name
  }
  return String(status || 'UNSPECIFIED')
}

function mapCatalogItem(item: any): CatalogItem {
  return {
    id: item.id || '',
    name: item.name || '',
    category: item.category || '',
    layer: item.layerLogicalId || '',
    owner: item.ownerTeamId || '',
    status: item.status?.toString() || '',
  }
}

function mapRequest(req: any): IaCRequest {
  // The proto status is a numeric RequestStatus enum; convert it to the
  // human-facing RequestStatus key the pages render (e.g. PLAN_READY →
  // 'plan_ready'). Unknown values fall back to the raw string so the UI can
  // surface unexpected backend responses.
  const rawStatus = req?.status
  const status = rawStatus == null ? '' : statusToKey(rawStatus)
  return {
    id: req.id || '',
    catalogItem: req.catalogItemId || '',
    env: req.envId || '',
    status,
    team: req.teamId || '',
    createdAt: req.createdAt || '',
    planArtifactId: req.planArtifactId || '',
  }
}

function mapModule(mod: any): Module {
  return {
    id: mod.id || '',
    name: mod.name || '',
    gitSource: mod.gitSource || '',
    modulePath: mod.modulePath || '',
    version: mod.version || '',
    provider: mod.provider || '',
    varCount: 0,
    outputCount: 0,
    status: mod.status?.toString() || '',
  }
}
